package in.jharkhand.civic.controller;
import in.jharkhand.civic.service.WorkflowService; import org.springframework.security.core.Authentication; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/projects") public class ProjectController {private final WorkflowService w;public ProjectController(WorkflowService w){this.w=w;} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT')") Map<String,Object> create(@RequestBody Map<String,Object> r,Authentication a){return w.createProject(a.getName(),r);}@GetMapping List<Map<String,Object>> all(){return w.projects();}@GetMapping("/{id}") Map<String,Object> one(@PathVariable String id){return w.project(id);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> update(@PathVariable String id,@RequestBody Map<String,Object> r){return w.updateProject(id,r);}@GetMapping("/{id}/milestones") List<Map<String,Object>> ms(@PathVariable String id){return w.milestones(id);}@PostMapping("/{id}/milestones") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> add(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.addMilestone(a.getName(),id,r);}@PutMapping("/milestones/{id}") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> upd(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.updateMilestone(a.getName(),id,r);}@GetMapping("/{id}/collaborations") List<Map<String,Object>> c(@PathVariable String id){return w.collaborations(id);}@PostMapping("/{id}/collaborations") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION','INDUSTRY')") Map<String,Object> cc(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.collaboration(a.getName(),id,r);}@PutMapping("/collaborations/{id}") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION','INDUSTRY')") Map<String,Object> cu(@PathVariable String id,@RequestBody Map<String,Object> r){return w.updateCollaboration(id,r);}@GetMapping("/{id}/impact") List<Map<String,Object>> impacts(@PathVariable String id){return w.impacts(id);}@PostMapping("/{id}/impact") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> impact(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.impact(a.getName(),"USER",id,r);}@PostMapping("/impact/{id}/verify") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> verify(@PathVariable String id,Authentication a){return w.verifyImpact(a.getName(),"ADMIN",id);} @PostMapping(value="/{id}/files",consumes="multipart/form-data") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> uploadFiles(@PathVariable String id,@RequestPart("files") List<MultipartFile> files,Authentication a)throws Exception{Path dir=Paths.get(w.dataDir().toString(),"uploads","projects",id);Files.createDirectories(dir);List<String> saved=new ArrayList<>();for(MultipartFile f:files){if(f==null||f.isEmpty())continue;String n=Path.of(Optional.ofNullable(f.getOriginalFilename()).orElse("file")).getFileName().toString();if(f.getSize()>10*1024*1024)throw new RuntimeException("File too large; maximum 10 MB");Files.copy(f.getInputStream(),dir.resolve(n),StandardCopyOption.REPLACE_EXISTING);saved.add(n);}Map<String,Object> current=w.project(id);List<String> all=new ArrayList<>();Object old=current.get("attachments");if(old instanceof List<?> l)l.forEach(x->all.add(String.valueOf(x)));all.addAll(saved);return w.updateProject(id,Map.of("attachments",all));}
 @PostMapping("/{id}/industry/invite") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> inviteIndustry(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.collaboration(a.getName(),id,r);}
}
